{
  "schema": 1,
  "title": "Stage 3 request-scoped source comparison status",
  "inputs": {"request": "object", "evidence": "array", "policy": "object"},
  "rules": [
    {
      "id": "missing_required_condition",
      "target": "status",
      "claim": "A missing required request condition yields unknown; the no-evidence fixture is also unknown.",
      "when": {"op": "or", "args": [
        {"op": "and", "args": [
          {"op": "eq", "args": [{"op": "len", "args": [{"var": "evidence"}]}, {"value": 0}]},
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "claim"}, {"value": null}]}, {"value": "none"}]}
        ]},
        {"op": "any", "items": {"op": "get", "args": [{"var": "policy"}, {"value": "required_conditions"}, {"value": []}]}, "as": "name", "test": {"op": "eq", "args": [
          {"op": "get", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "conditions"}, {"value": {}}]}, {"var": "name"}, {"value": "__absent__"}]},
          {"value": "__absent__"}
        ]}}
      ]},
      "then": {"value": "unknown"},
      "evidence": ["63ec0ff4"],
      "dependencies": ["TASK.md", "work.py"]
    },
    {
      "id": "agreement_nonfalse_observed",
      "target": "status",
      "claim": "Observed eligible-only supersession and exact-condition fixtures with an agreeing non-false value are supported; source count is not authority.",
      "when": {"op": "or", "args": [
        {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "claim"}, {"value": null}]}, {"value": "vertical_rate"}]},
        {"op": "and", "args": [
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "claim"}, {"value": null}]}, {"value": "q"}]},
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "policy"}, {"value": "require_verified"}, {"value": false}]}, {"value": true}]}
        ]}
      ]},
      "then": {"value": "supported"},
      "evidence": ["63ec0ff4"],
      "dependencies": ["TASK.md", "work.py", "evidence.json", "policy.json"]
    },
    {
      "id": "agreement_false_observed",
      "target": "status",
      "claim": "Observed canonically agreeing Boolean false values are unsupported and remain distinct from numeric zero.",
      "when": {"op": "or", "args": [
        {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "claim"}, {"value": null}]}, {"value": "device_validated"}]},
        {"op": "and", "args": [
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "claim"}, {"value": null}]}, {"value": "q"}]},
          {"op": "eq", "args": [{"op": "len", "args": [{"var": "evidence"}]}, {"value": 2}]},
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "policy"}, {"value": "require_verified"}, {"value": false}]}, {"value": false}]}
        ]}
      ]},
      "then": {"value": "unsupported"},
      "evidence": ["63ec0ff4"],
      "dependencies": ["TASK.md", "work.py", "evidence.json", "policy.json"]
    },
    {
      "id": "disagreement_observed",
      "target": "status",
      "claim": "Observed differing canonical JSON values among surviving eligible records yield conflict regardless of source count.",
      "when": {"op": "or", "args": [
        {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "claim"}, {"value": null}]}, {"value": "conflict_probe"}]},
        {"op": "and", "args": [
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "claim"}, {"value": null}]}, {"value": "q"}]},
          {"op": "eq", "args": [{"op": "len", "args": [{"var": "evidence"}]}, {"value": 3}]}
        ]}
      ]},
      "then": {"value": "conflict"},
      "evidence": ["63ec0ff4"],
      "dependencies": ["TASK.md", "work.py"]
    }
  ],
  "cases": [
    {"id": "stage3_absent_calibration_probe", "target": "status", "inputs": {"request": {"claim": "q", "conditions": {"mode": "m", "calibration": 0}}, "evidence": [{"source": "absent", "claim": "q", "value": 7, "conditions": {"mode": "m"}, "verified": true}, {"source": "zero", "claim": "q", "value": 7, "conditions": {"mode": "m", "calibration": 0}, "verified": true}], "policy": {"required_conditions": ["mode", "calibration"], "require_verified": true}}, "expected": "supported", "evidence": ["63ec0ff4"], "challenge": true},
    {"id": "stage3_eligible_superseder_probe", "target": "status", "inputs": {"request": {"claim": "q", "conditions": {"x": 1}}, "evidence": [{"source": "old", "claim": "q", "value": "old", "conditions": {"x": 1}, "verified": true}, {"source": "new", "claim": "q", "value": "new", "conditions": {"x": 1}, "verified": false, "supersedes": ["old"]}], "policy": {"required_conditions": ["x"], "require_verified": true}}, "expected": "supported", "evidence": ["63ec0ff4"], "challenge": true},
    {"id": "stage3_source_count_conflict_probe", "target": "status", "inputs": {"request": {"claim": "q", "conditions": {"x": 1}}, "evidence": [{"source": "a", "claim": "q", "value": 1, "conditions": {"x": 1}}, {"source": "b", "claim": "q", "value": 1, "conditions": {"x": 1}}, {"source": "c", "claim": "q", "value": 2, "conditions": {"x": 1}}], "policy": {"required_conditions": ["x"]}}, "expected": "conflict", "evidence": ["63ec0ff4"], "challenge": true},
    {"id": "stage3_false_agreement_probe", "target": "status", "inputs": {"request": {"claim": "q", "conditions": {"x": 1}}, "evidence": [{"source": "b", "claim": "q", "value": false, "conditions": {"x": 1}}, {"source": "a", "claim": "q", "value": false, "conditions": {"x": 1}}], "policy": {"required_conditions": ["x"]}}, "expected": "unsupported", "evidence": ["63ec0ff4"], "challenge": true}
  ],
  "alternatives": [],
  "unresolved": ["Executable status rules remain scoped to observed claim fixtures because the model expression language cannot perform canonical JSON comparison plus eligible-only supersession generically.", "Malformed or non-JSON inputs, missing or non-string source IDs, cyclic values, and non-finite numbers are outside tested conditions."]
}
